<script>
  import TextInput from './TextInput.svelte'

  let {
    name = 'hp',
    value = $bindable(''),
    class: klass = '',
    ...rest
  } = $props()
</script>

<!-- `autocomplete="off"` keeps the browser from filling a field named after a real one, which would reject a real person as a bot. `tabindex` and `aria-hidden` keep keyboard and screen reader users out of the field. -->
<TextInput
  {...rest}
  {name}
  class="form-field-helper {klass}"
  autocomplete="off"
  tabindex="-1"
  aria-hidden="true"
  bind:value
/>
